{"command":"python3 - <<'PY'
import json
from collections import deque, OrderedDict

cfg=json.load(open('/root/config.json'))
block_size=cfg['block_size']
capacity=cfg['cache_capacity_blocks']
small_cap=round(capacity*cfg['s3fifo']['small_ratio'])
main_cap=capacity-small_cap
max_freq=cfg['s3fifo']['max_freq']

S=deque(); Sset=set(); Sfreq={}
M=deque(); Mset=set(); Mfreq={}
G=OrderedDict()

per=[]
total_prompt=0
total_hit=0


def insert_G(h):
    if h in G:
        G.pop(h)
    else:
        if len(G) >= main_cap:
            G.popitem(last=False)
    G[h]=None


def admit_M(h, freq):
    global M
    while len(M) >= main_cap:
        victim=M[0]
        vf=Mfreq[victim]
        if vf >= 1:
            M.popleft()
            Mfreq[victim]=vf-1
            M.append(victim)
        else:
            M.popleft(); Mset.remove(victim); del Mfreq[victim]
            insert_G(victim)
            break
    M.append(h); Mset.add(h); Mfreq[h]=freq


def admit_S(h):
    while len(S) >= small_cap:
        victim=S.popleft(); vf=Sfreq.pop(victim); Sset.remove(victim)
        if vf >= 1:
            admit_M(victim, vf)
        else:
            insert_G(victim)
    S.append(h); Sset.add(h); Sfreq[h]=0

for idx,line in enumerate(open('/root/trace.jsonl')):
    req=json.loads(line)
    hashes=req['hash_ids']
    L=req['input_length']
    total_prompt += L
    k=0
    for h in hashes:
        if h in Sset or h in Mset:
            k += 1
        else:
            break
    hit=min(k*block_size, L)
    total_hit += hit
    per.append({'idx': idx, 'prompt_tokens': L, 'hit_tokens': hit})
    for h in hashes:
        if h in Sset:
            Sfreq[h]=min(Sfreq[h]+1, max_freq)
        elif h in Mset:
            Mfreq[h]=min(Mfreq[h]+1, max_freq)
        elif h in G:
            G.pop(h)
            admit_M(h, 0)
        else:
            admit_S(h)

report={
    'total_requests': len(per),
    'total_prompt_tokens': total_prompt,
    'total_hit_tokens': total_hit,
    'overall_hit_rate': total_hit/total_prompt if total_prompt else 0,
    'final_cache_blocks': len(Sset)+len(Mset),
    'per_request': per,
}
json.dump(report, open('/root/report.json','w'), ensure_ascii=False)
print(report['total_requests'], report['total_prompt_tokens'], report['total_hit_tokens'], report['overall_hit_rate'], report['final_cache_blocks'])
PY"}
